#!/usr/bin/env -S deno run --allow-read --allow-write
// sync-shared.ts — copy the rules two clients share from their ONE source.
//
// CONTRACT (MESITA-3302, MESITA-4930):
//   _shared/money-state.ts   = SOURCE. What a place sells and how a guest
//                              can pay. Hand-edited.
//   _shared/money-codes.ts   = SOURCE. Every code a money EF answers with.
//   packages/place-profile/src/money-state.ts, money-codes.ts
//                            = FULLY GENERATED byte-identical copies.
//   packages/place-profile/src/** (the modules in MOBILE_MODULES)
//                            = SOURCE of the place's pure rules. Hand-edited.
//   apps/mobile-consumer/src/generated/shared/**
//                            = FULLY GENERATED byte-identical copies, laid out
//                              like packages/place-profile/src: the two money
//                              modules, MOBILE_MODULES, and every module those
//                              import by relative path. Nothing else lives there.
//
// Why copy instead of import: the monorepo has NO root pnpm workspace on
// purpose (each package is its own install root), so there is no import
// path the package can reach. Same idiom as sync-rules.ts and sync-brand.ts:
// generate, and gate with --check in CI. The twins import nothing, so the
// same bytes compile under Deno and under the package's TypeScript.
//
// The phone has no browser and none of the package's dependencies, so a module
// that reaches a package import or a browser global is refused by name, and
// nothing is written.
//
// Run from the repo root:
//     deno task sync-shared
// Pass --check to verify without writing (STRICT: any drift exits 1).
// money-twins.test.ts in _shared pins the twins' equality from the Deno side.

import { dirname, fromFileUrl, join, normalize } from "@std/path";
import { stripComments } from "./vocabulary-ratchet.ts";

const repoRoot = dirname(dirname(fromFileUrl(import.meta.url)));

const SOURCE_DIR = "supabase/supabase/functions/_shared";
const PACKAGE_DIR = "packages/place-profile/src";
const MOBILE_DIR = "apps/mobile-consumer/src/generated/shared";
// MESITA-4708: pay-split.ts (the Pay form's card split) left with the card
// part of a bill.
export const TWINS = ["money-state.ts", "money-codes.ts"] as const;

/** The place-profile modules the phone app uses, relative to PACKAGE_DIR. A
 *  module joins when a feature first needs it; its imports follow by themselves. */
export const MOBILE_MODULES = ["lib/offers.ts", "place-to-detail.ts"] as const;

const IMPORT = /\b(?:from|import)\s*\(?\s*(["'])([^"'\n]+)\1/g;
const BROWSER_GLOBAL =
  /(?<![.\w$])(?:typeof\s+)?(window|document|navigator|localStorage|sessionStorage)(?=\s*(?:\?\.|\.|\[))|\btypeof\s+(window|document|navigator)\b/g;

export type Refusal = { module: string; line: number; what: string; fix: string };

/** Every specifier a module imports or re-exports, with its line. */
export function importsOf(source: string): { specifier: string; line: number }[] {
  const code = stripComments(source);
  return [...code.matchAll(IMPORT)].map((m) => ({
    specifier: m[2],
    line: code.slice(0, m.index).split("\n").length,
  }));
}

/** Why the phone cannot run this module as it stands. */
export function refusalsOf(module: string, source: string): Refusal[] {
  const code = stripComments(source);
  const out: Refusal[] = importsOf(source)
    .filter(({ specifier }) => !specifier.startsWith("."))
    .map(({ specifier, line }) => ({
      module,
      line,
      what: `imports the package "${specifier}"`,
      fix: "move what needs it into its own module, so this one stays pure",
    }));
  for (const m of code.matchAll(BROWSER_GLOBAL)) {
    out.push({
      module,
      line: code.slice(0, m.index).split("\n").length,
      what: `reads the browser global ${m[1] ?? m[2]}`,
      fix: "take the value as an argument",
    });
  }
  return out;
}

/** `modules` and everything they reach by relative import, read with `read`. */
export async function closure(
  modules: readonly string[],
  read: (module: string) => Promise<string | null>,
): Promise<{ files: Map<string, string>; refusals: Refusal[] }> {
  const files = new Map<string, string>();
  const refusals: Refusal[] = [];
  const queue = [...modules];
  for (let module = queue.shift(); module !== undefined; module = queue.shift()) {
    if (files.has(module)) continue;
    const source = await read(module);
    if (source === null) {
      refusals.push({ module, line: 0, what: "does not exist", fix: "correct MOBILE_MODULES in scripts/sync-shared.ts" });
      continue;
    }
    files.set(module, source);
    refusals.push(...refusalsOf(module, source));
    for (const { specifier, line } of importsOf(source)) {
      if (!specifier.startsWith(".")) continue;
      const target = `${normalize(join(dirname(module), specifier)).replace(/\.ts$/, "")}.ts`;
      if (target.startsWith("..") || await read(target) === null) {
        refusals.push({
          module,
          line,
          what: `imports "${specifier}", which is not a .ts module inside ${PACKAGE_DIR}`,
          fix: "import a plain .ts module of the package",
        });
        continue;
      }
      queue.push(target);
    }
  }
  return { files, refusals };
}

async function readOrNull(path: string): Promise<string | null> {
  try {
    return await Deno.readTextFile(path);
  } catch (e) {
    if (e instanceof Deno.errors.NotFound) return null;
    throw e;
  }
}

async function listFiles(dir: string, under = ""): Promise<string[]> {
  const out: string[] = [];
  try {
    for await (const entry of Deno.readDir(join(dir, under))) {
      const path = under === "" ? entry.name : `${under}/${entry.name}`;
      if (entry.isDirectory) out.push(...await listFiles(dir, path));
      else out.push(path);
    }
  } catch (e) {
    if (!(e instanceof Deno.errors.NotFound)) throw e;
  }
  return out;
}

async function main(check: boolean): Promise<void> {
  const twins = new Set<string>(TWINS);
  const sourceOf = (module: string) =>
    twins.has(module) ? `${SOURCE_DIR}/${module}` : `${PACKAGE_DIR}/${module}`;

  const { files, refusals } = await closure(
    [...TWINS, ...MOBILE_MODULES],
    (module) => readOrNull(join(repoRoot, sourceOf(module))),
  );
  if (refusals.length > 0) {
    for (const r of refusals) {
      console.error(`REFUSED: ${sourceOf(r.module)}:${r.line} ${r.what} — ${r.fix}`);
    }
    Deno.exit(1);
  }

  const wanted: { target: string; source: string; text: string }[] = [
    ...TWINS.map((name) => ({ target: `${PACKAGE_DIR}/${name}`, source: sourceOf(name), text: files.get(name)! })),
    ...[...files].map(([module, text]) => ({ target: `${MOBILE_DIR}/${module}`, source: sourceOf(module), text })),
  ];

  let drift = 0;
  for (const { target, source, text } of wanted) {
    const have = await readOrNull(join(repoRoot, target));
    if (have === text) continue;
    if (check) {
      console.error(`DRIFT: ${target} ${have === null ? "is missing" : "differs from"} ${source}`);
      drift++;
      continue;
    }
    await Deno.mkdir(dirname(join(repoRoot, target)), { recursive: true });
    await Deno.writeTextFile(join(repoRoot, target), text);
    console.log(`wrote ${target}`);
  }
  for (const module of await listFiles(join(repoRoot, MOBILE_DIR))) {
    if (files.has(module)) continue;
    if (check) {
      console.error(`DRIFT: ${MOBILE_DIR}/${module} has no source`);
      drift++;
      continue;
    }
    await Deno.remove(join(repoRoot, MOBILE_DIR, module));
    console.log(`removed ${MOBILE_DIR}/${module}`);
  }

  if (check) {
    if (drift > 0) {
      console.error(`${drift} shared module(s) out of sync — run: deno task sync-shared`);
      Deno.exit(1);
    }
    console.log(`shared modules in sync (${wanted.length})`);
  }
}

if (import.meta.main) await main(Deno.args.includes("--check"));
